"""Source of the concept graph. `python scripts/build_knowledge.py` writes concepts.json.

All examples are ILLUSTRATIVE / FICTIONAL. Nothing here recommends any investment.
Quiz distractors may carry a misconception id so quiz answers feed the misconception engine.
"""


def Q(id, q, options, correct, explain, difficulty=1):
    return {"id": id, "question": q, "options": [{"text": t, "misconception_id": m} for t, m in options],
            "correct_index": correct, "explanation": explain, "difficulty": difficulty}


def C(id, name, category, simple, detailed, examples, related, miscs, quiz, scenarios, aliases, simulation=None,
      name_hi=None, name_hing=None):
    return {"id": id, "name": {"en": name, "hinglish": name_hing or name, "hi": name_hi or name}, "category": category,
            "simple": simple, "detailed": detailed, "examples": examples, "related": related, "misconceptions": miscs,
            "quiz": quiz, "scenarios": scenarios, "aliases": aliases, "simulation": simulation}


